  $('#lcaste').on('change', function() {
    $("#caste_before_mod").css("display", "none");
    $("#caste_before_mod").css("width", "160px");
    $("#subcaste_before_mod").css("display", "none");
    $("#subcaste_before_mod").css("width", "160px");
    $("#subcaste_toolbox").html("This field can be changed only once.");
    $("#caste_toolbox").html("This field can be changed only once.");
    $("#caste_before_mod").css("display", "inline-block");
    $("#caste_before_mod").show();
  });

  $('#subcastediv').on('change', function() {

        if($("#newrealigion").val()!=3){
            $("#subcaste_before_mod").css('display', 'inline-block');
            $("#subcaste_before_mod").show();
        }
    });

});


