    <script>
        $(document).ready(function() {

            ////new work related right panel
            loadrand();
            $("#less").hide();
            $("#more").click(function() {
                $(".rightdivele").show();
                $("#less").show();
                $("#more").hide();
            });
            $("#less").click(function() {
                loadrand();
                $("#more").show();
                $("#less").hide();
            });
        });

        function loadrand() {
            $(".rightdivele").hide();
            var elements = $(".rightdivele");
            var elementCount = elements.size();
            if (elementCount == 1) {
                var elementsToShow = 1;
                $("#more").css("display", "none");
            } else if (elementCount == 2) {
                var elementsToShow = 2;
                $("#more").css("display", "none");
            } else if (elementCount > 2) {
                var elementsToShow = 2;
                $("#more").css("display", "block");
            } else if (elementCount == 0) {
                $(".RightPanel").hide();
            }
            var alreadyChoosen = ",";
            var i = 0;
            while (i < elementsToShow) {
                var rand = Math.floor(Math.random() * elementCount);
                if (alreadyChoosen.indexOf("," + rand + ",") < 0) {
                    alreadyChoosen += rand + ",";
                    elements.eq(rand).show();
                    ++i;
                }
            }
        }
        function skiponloading() {
            $(".Displayedit .Displayeditlist:first-child").css("display", "block");
            var size = $(".Displayeditlist").length;
            if (size == 0) {
                $('.nt').hide();
            }
        }
        var increment = 0;
        function Skip() {
            var size = $(".Displayeditlist").length;
            var Displaycount = $('#Displaycount').val();
            $(".Displayedit .Displayeditlist:visible").next().show().prev().hide();
            increment++;
            if (increment == Displaycount || increment == size) {
                $('.nt').remove();
                $(".Displayedit").hide();
            }
        }
    </script>
