<script>
    function backTop() {
        if ($('#container1').css('display') == 'block') {
            // hide #back-top first
            $('#container1').after('<div style="display: none;" id="back-top" class="active"><a href="#container1"><span><!-- --></span></a></div>');
            $("#back-top").hide();

            // fade in #back-top
            $(function() {
                $(window).scroll(function() {
                    if ($(this).scrollTop() > 600) {
                        $('#back-top').fadeIn();
                    } else {
                        $('#back-top').fadeOut();
                    }
                });
            });
        }
    }
    if ($.browser.version.substr(0, 1) != 6) {
        $(document).ready(function() {
            backTop();
        });
    }
</script>
