    $(document).ready(function() {
        var FamilyVal = $('input[name="FAMILYLOCATIONSTATUS"]:checked').val();
        if (FamilyVal == 2) {
            document.getElementById('familylocation').style.display = "block";
        }
    });
    function sameasme() {
        document.getElementById('familylocation').style.display = "none";
        document.getElementById('famdifflocation').checked = false;
    }
    function difflocation() {
        document.getElementById('famsameasme').checked = false;
        var FamilyVal = $('input[name="FAMILYLOCATIONSTATUS"]:checked').val();
        if (FamilyVal == undefined) {
            document.getElementById('familylocation').style.display = "none";
        } else {
            document.getElementById('familylocation').style.display = "block";
        }
    }

    function familynetworth() {
        var familystatus = $('input[name="FAMILYSTATUS"]:checked').val();
        if (familystatus == 4) {
            $("#familynetworth").show();
        } else {
            $("#familynetworth").hide();
        }
    }
</script>
