<script>
    function paPopup(paStar, paPhotoAvail, paHoroAvail) {
        hidePADiv();
        if (paStar == '0') {
            $('#pa-star-div').css('display', 'block');
        } else if (paPhotoAvail == '0') {
            $('#pa-photo-div').css('display', 'block');
        } else if (paHoroAvail == '0') {
            $('#pa-horo-div').css('display', 'block');
        } else if (paPhotoAvail == '' && paHoroAvail != '0') {
            //photo popup last	
            paPopupClose();
        }
    }
    function hidePADiv() {
        $('#pa-div5').css('display', 'none');
        $('#pa-star-div').css('display', 'none');
        $('#pa-photo-div').css('display', 'none');
        $('#pa-horo-div').css('display', 'none');
    }
    function paPopupClose() {
        $("#popbxpart").hide();
        $("#popbxoverlay").hide();
        $("#popbox").hide();
    }

    function callPASubmitGA(flag) {
        domain_mt = "MARATHI";
        if (flag == 1) {
            ga('send', 'event', 'Profile-Analyzer-' + domain_mt, 'Star', 'Submit');
            _gaq.push(["_trackEvent", 'Profile-Analyzer-' + domain_mt, 'Star', 'Submit']);
        } else if (flag == 2) {
            ga('send', 'event', 'Profile-Analyzer-' + domain_mt, 'addphoto', 'click');
            _gaq.push(["_trackEvent", 'Profile-Analyzer-' + domain_mt, 'addphoto', 'click']);
        } else if (flag == 3) {
            ga('send', 'event', 'Profile-Analyzer-' + domain_mt, 'generatehoro', 'click');
            _gaq.push(["_trackEvent", 'Profile-Analyzer-' + domain_mt, 'generatehoro', 'click']);
        }
    }
    function callPASkipGA(flag) {
        domain_mt = "MARATHI";
        if (flag == 1) {
            ga('send', 'event', 'Profile-Analyzer-' + domain_mt, 'Star', 'skip');
            _gaq.push(["_trackEvent", 'Profile-Analyzer-' + domain_mt, 'Star', 'skip']);
        } else if (flag == 2) {
            ga('send', 'event', 'Profile-Analyzer-' + domain_mt, 'addphoto', 'skip');
            _gaq.push(["_trackEvent", 'Profile-Analyzer-' + domain_mt, 'addphoto', 'skip']);
        } else if (flag == 3) {
            ga('send', 'event', 'Profile-Analyzer-' + domain_mt, 'generatehoro', 'close');
            _gaq.push(["_trackEvent", 'Profile-Analyzer-' + domain_mt, 'generatehoro', 'close']);
        }
    }

    $(document).ready(function() {
        setTimeout(function() {
            $("#popbox").myLightBox(700, 450)
        }, 2000);
    });
</script>
