<script type="text/javascript">
    $(document).ready(function() {
        $(window).scroll(function() {
            $("#good_bad_banner").css({
                "position": "",
                "top": ""
            });

            if ($("#good_bad_banner_top").length > 0) {
                if ($("#good_bad_banner_top")[0].getBoundingClientRect().bottom < 50) {
                    $('#good_bad_banner').addClass('good_bad_banner_fixed');

                    if ($("#good_bad_banner").is(":visible")) {
                        if ($("#good_bad_banner").offset().top > $("#desc_banner_top").offset().top) {
                            $("#good_bad_banner").removeClass('good_bad_banner_fixed');
                        }
                        /*else{
            $("#good_bad_banner").show();
           }*/
                    }

                } else {
                    $('#good_bad_banner').removeClass('good_bad_banner_fixed');
                }
            } else {

                $('#good_bad_banner').removeClass('good_bad_banner_fixed');
            }
        });
    });

    function loadinstmatchescount(type) {
        $("#good_bad_banner").show();

        if (type == '1')
            bannertop = 'good_bad_banner_top';
        else if (type == '2')
            bannertop = 'professional_banner_top';
        else if (type == '3')
            bannertop = 'location_banner_top';
        else if (type == 'editpp')
            bannertop = 'good_bad_banner_editpp';

        var fixbannertopinst = $("#" + bannertop).offset();
        $("#good_bad_banner").offset({
            top: fixbannertopinst.top
        });

        $("#changed_mothertongue").val($("#MOTHERTONGUE_OUT").val());
        var castereplace = $("#CASTE_OUT").val();
        var castereplaceVal = castereplace.replace(/Caste_/g, '');
        $("#changed_caste").val(castereplaceVal);
        $("#changed_gothra").val($("#GOTHRA_OUT").val());
        $("#changed_subcaste").val($("#SUBCASTE_OUT").val());
        $("#changed_star").val($("#STAR_OUT").val());
        $("#changed_occupation").val($("#OCCUPATION_OUT").val());
        $("#changed_employed").val($("#EMPLOYED_OUT").val());

        var ORGCOUNTRY_OUT = $('#COUNTRY_OUT').val();
        Countryinstpp = ORGCOUNTRY_OUT.replace(/cnt_/g, '');
        $("#changed_country").val(Countryinstpp);

        var ORGSTATE_OUT = $('#STATE_OUT').val();
        Stateinstpp = ORGSTATE_OUT.replace(/state_/g, '');
        $("#changed_state").val(Stateinstpp);

        var ORGCITY_OUT = $('#CITY_OUT').val();
        Cityinstpp = ORGCITY_OUT.replace(/[0-9]*#/g, '');
        $("#changed_city").val(Cityinstpp);

        var ORGCITIZENSHIP_OUT = $('#CITIZENSHIP_OUT').val();
        Citizenshipinstpp = ORGCITIZENSHIP_OUT.replace(/cnt_/g, '');
        $("#changed_citizenship").val(Citizenshipinstpp);

        var appendInstDataInitialUrl = appendInstData();

        if ($("#alreadysysppset").val() == '') {
            $.ajax({
                type: "POST",
                url: "https://profile." + DOMAINARRAY['domainnameshort'] + "matrimony.com/register/getdynamicmatchcount.php",
                //data: "memberid=R6404490&partnerprefset=&gothraid=0&age=18&gender=F&extraparam="+appendInstDataInitialUrl,
                data: "extraparam=" + appendInstDataInitialUrl + "&instppvalues=" + $("#instppvalues").val(),
                crossDomain: true,
                success: function(response) {
                    if (response != '') {
                        //alert('default count entered----');
                        $("#matchcountinstcount").html(response);
                        response = parseInt(response);
                        if (response == 1) {
                            $("#chnginstcontent").html('matching profile.');
                        }
                        $("#imgindicator").html('<img src="https://imgs.marathidating.com/bmimgs/pp-neutral.png" width="140" height="86" border="0" alt="">');
                        $("#sysppcount").val(response);
                        $("#alreadysysppset").val('1');
                    }
                }
            });
        }
    }

    function remove_instcountbanner() {
        $("#good_bad_banner").removeClass("good_bad_banner_fixed");
        $("#good_bad_banner").hide();
    }
</script>
